def fill_matrix(n, k):
    if k > n * n / 2:
        return -1

    matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i, n):
            if k > 0:
                matrix[i][j] = 1
                matrix[j][i] = 1
                k -= 1

    return matrix

def main():
    n, k = map(int, input().split())
    result = fill_matrix(n, k)
    if result == -1:
        print(-1)
    else:
        for row in result:
            print(' '.join(map(str, row)))

if __name__ == "__main__":
    main()
